        ('EUROPA', 412, 'europe', 'Gree', '12 АМБЪР', '4M24550003658', '4K43850007174', '2026-03-23'::date, 'ДИМЕЛИ', '4651', 780.0::numeric(10,2), NULL::date, 'Здравко Мирчев БАНИТЕ', '0878 143 221', NULL::text, NULL::text, 1145.0::numeric(10,2), 'Импорт AERF VTORA, лист EUROPA ред 412 · доставчик: ДИМЕЛИ · ф-ра доставка: 4651'),
