        ('EUROPA', 420, 'europe', 'Gree', '12 АМБЪР', '4М24540008923', '4К43850007188', '2026-03-23'::date, 'ДИМЕЛИ', '4651', 780.0::numeric(10,2), '2026-04-08'::date, 'ПЕТКО ПЕТКОВ', '0888 923 356', NULL::text, NULL::text, 1200.0::numeric(10,2), 'Импорт AERF VTORA, лист EUROPA ред 420 · доставчик: ДИМЕЛИ · ф-ра доставка: 4651'),
